(1011003, 121076, 6870, '<td valign="top">This is really glorious. I love the soft, soft focus and composition still applies very nicely 10</td>', 'This is really glorious. I love the soft, soft focus and composition still applies very nicely 10', '2004-11-15 00:17:46.000000', NULL, 1),
(1011008, 121246, 22975, '<td valign="top">This is beautiful, but-- and this is just my opinion-- I think it would have been a tad better had the sharp rock in the foreground been removed.  Everything else is just so soft and pretty, and I feel like the close rock challenges the mood of the photo.  It''s a great shot, though... 9</td>', 'This is beautiful, but-- and this is just my opinion-- I think it would have been a tad better had the sharp rock in the foreground been removed.  Everything else is just so soft and pretty, and I feel like the close rock challenges the mood of the photo.  It''s a great shot, though... 9', '2004-11-15 00:18:54.000000', NULL, 1),
(1011009, 120552, 27293, '<td valign="top">I would have made the whole shot in a nice bokeh, just like the left third.</td>', 'I would have made the whole shot in a nice bokeh, just like the left third.', '2004-11-15 00:19:07.000000', NULL, 1),
(1011010, 119770, 6870, '<td valign="top">Very intriguing. This reminds me of some of the interesting old processing techniques for film. Lines and textures are very interesting to me. 8</td>', 'Very intriguing. This reminds me of some of the interesting old processing techniques for film. Lines and textures are very interesting to me. 8', '2004-11-15 00:19:12.000000', NULL, 1),
