(1012445, 121187, 26464, '<td valign="top">impressive..</td>', 'impressive..', '2004-11-15 18:56:19.000000', NULL, 1),
(1012448, 120208, 23394, '<td valign="top">nice composition, lighting, and colors.  the texture, though, feels somewhat artificial, and leaves me feeling as though i''ve had enough, rather than leaving me wanting to gaze longer.</td>', 'nice composition, lighting, and colors.  the texture, though, feels somewhat artificial, and leaves me feeling as though i''ve had enough, rather than leaving me wanting to gaze longer.', '2004-11-15 18:57:10.000000', NULL, 1),
(1012450, 119770, 26464, '<td valign="top">very stark and emotive.. well done.<br/></td>', 'very stark and emotive.. well done.', '2004-11-15 18:57:59.000000', NULL, 1),
(1012451, 119970, 23394, '<td valign="top">while appreciate the affect you wanted to achieve, i wish you had achieved slightly less of it.  the colors, lighting, and general composition all work well, but the double-imagery is a little disconcerting.</td>', 'while appreciate the affect you wanted to achieve, i wish you had achieved slightly less of it.  the colors, lighting, and general composition all work well, but the double-imagery is a little disconcerting.', '2004-11-15 18:59:19.000000', NULL, 1),
