(1013136, 121274, 28097, '<td valign="top">the water and the bubles are beautifull but i''m afraid the blue tiles are not helping the picture.. my opinion anyway .. good picture</td>', 'the water and the bubles are beautifull but i''m afraid the blue tiles are not helping the picture.. my opinion anyway .. good picture', '2004-11-16 02:49:35.000000', NULL, 1),
(1013137, 120858, 28097, '<td valign="top">beautifull colors and lighting..  the water reflection is just right... fits the challenge too ... good job...</td>', 'beautifull colors and lighting..  the water reflection is just right... fits the challenge too ... good job...', '2004-11-16 02:52:31.000000', NULL, 1),
(1013141, 121055, 14193, '<td valign="top">I am just not a big fan of using post editing to "make" the picture. I like the idea some others had of using water reflections and shower glass to get the impressionist effect. I am sure that the original picture here was beautiful, but you can''t tell because of the post editing.</td>', 'I am just not a big fan of using post editing to "make" the picture. I like the idea some others had of using water reflections and shower glass to get the impressionist effect. I am sure that the original picture here was beautiful, but you can''t tell because of the post editing.', '2004-11-16 02:56:52.000000', NULL, 1),
(1013143, 120858, 14193, '<td valign="top">This is just outstanding. I love the effect here done with the water reflection and just a whisp of fog. What a great eye. You are truly a master. (10)</td>', 'This is just outstanding. I love the effect here done with the water reflection and just a whisp of fog. What a great eye. You are truly a master. (10)', '2004-11-16 02:58:22.000000', NULL, 1),
(1013144, 121425, 14193, '<td valign="top">Brilliant idea with the shower glass to break up the beautiful image. It is definately an impressionists picture. Gorgeous. (9)</td>', 'Brilliant idea with the shower glass to break up the beautiful image. It is definately an impressionists picture. Gorgeous. (9)', '2004-11-16 02:59:24.000000', NULL, 1),
(1013147, 120208, 14193, '<td valign="top">This is so beautiful, I am anxious to see how you accomplished the softness here. (9)</td>', 'This is so beautiful, I am anxious to see how you accomplished the softness here. (9)', '2004-11-16 03:00:23.000000', NULL, 1),
(1013148, 120752, 14193, '<td valign="top">The clarity and color is outstanding. A wonderful idea, too. Good shot. (9)</td>', 'The clarity and color is outstanding. A wonderful idea, too. Good shot. (9)', '2004-11-16 03:01:06.000000', NULL, 1),
(1013151, 121025, 14193, '<td valign="top">Too much post editing. This would have looked better with a little blur or shot through milky glass or something. I just don''t really care for a picture that is obviously post edited.</td>', 'Too much post editing. This would have looked better with a little blur or shot through milky glass or something. I just don''t really care for a picture that is obviously post edited.', '2004-11-16 03:03:15.000000', NULL, 1),
(1013152, 121422, 14193, '<td valign="top">This is a pretty shot, but just "looks" to post edited. I prefer a picture that gets the effect with camera skill, not computer skill. Just my preference.</td>', 'This is a pretty shot, but just "looks" to post edited. I prefer a picture that gets the effect with camera skill, not computer skill. Just my preference.', '2004-11-16 03:05:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1013182, 121280, 3214, '<td valign="top">Absolutely terrific</td>', 'Absolutely terrific', '2004-11-16 03:39:39.000000', NULL, 1),
(1013187, 120548, 29182, '<td valign="top">wow..  nice colors</td>', 'wow..  nice colors', '2004-11-16 03:46:48.000000', NULL, 1),
(1013285, 120858, 6999, '<td valign="top">The curve in the reflection nicely quotes the Water Lillies, and I do like the array of tones in the fallen leaves. Photographically, I find it a touch too washed out as it moves up the image: I think you perhaps had enough here to speak of ''impressionism'', without that extra  push, be it from natural light or from processing. I don''t know that I wouldn''t have warmed the colour temperature of the whole thing a little either - it just has a slightly cold feel to it, slightly too far to blue.<br/> <br/>But it works for the challenge, nicely, of course. The drfit, as the eye rises, from a genuinely photographic feel into a world of paint-like appearance (and a world I fully expect to see over-used in this challenge), makes a subtle point. Enjoyable.</td>', 'The curve in the reflection nicely quotes the Water Lillies, and I do like the array of tones in the fallen leaves. Photographically, I find it a touch too washed out as it moves up the image: I think you perhaps had enough here to speak of ''impressionism'', without that extra  push, be it from natural light or from processing. I don''t know that I wouldn''t have warmed the colour temperature of the whole thing a little either - it just has a slightly cold feel to it, slightly too far to blue. But it works for the challenge, nicely, of course. The drfit, as the eye rises, from a genuinely photographic feel into a world of paint-like appearance (and a world I fully expect to see over-used in this challenge), makes a subtle point. Enjoyable.', '2004-11-16 06:45:32.000000', NULL, 1),
(1013291, 121426, 3306, '<td valign="top">Very attractive, simple and effective. I like the way the subject blends into the backround and yet is dominent enough to maintain the viewers attention.</td>', 'Very attractive, simple and effective. I like the way the subject blends into the backround and yet is dominent enough to maintain the viewers attention.', '2004-11-16 06:59:36.000000', NULL, 1),
(1013293, 121188, 3306, '<td valign="top">An attractive windmill picture with just the right amount of filter to give it that impressionistic feeling. Well done.</td>', 'An attractive windmill picture with just the right amount of filter to give it that impressionistic feeling. Well done.', '2004-11-16 07:01:10.000000', NULL, 1),
(1013296, 120987, 3306, '<td valign="top">I like the soft reflective focus on your image. The filtering is not overpowering. Although not a complicated picture in imagery it is very pleasing to the eye.</td>', 'I like the soft reflective focus on your image. The filtering is not overpowering. Although not a complicated picture in imagery it is very pleasing to the eye.', '2004-11-16 07:04:18.000000', NULL, 1),
(1013300, 120552, 3306, '<td valign="top">This picture shows that you have alot of photographic talent. You have given much thought to the positioning, DOF, lighing and subject matter and accomplished it all extremely well.</td>', 'This picture shows that you have alot of photographic talent. You have given much thought to the positioning, DOF, lighing and subject matter and accomplished it all extremely well.', '2004-11-16 07:07:35.000000', NULL, 1),
(1013311, 117658, 92, '<td valign="top">Now THIS IS what the challenge is all about. VERY well done ! Good luck ! 10</td>', 'Now THIS IS what the challenge is all about. VERY well done ! Good luck ! 10', '2004-11-16 07:16:33.000000', NULL, 1),
(1013313, 119770, 92, '<td valign="top">Just WOW ! This is just amazing. It doesn''t have the color but the impact makes it work. The composition and the fact that it has such a wow impact makes this a winner !  Wonderful !<br/></td>', 'Just WOW ! This is just amazing. It doesn''t have the color but the impact makes it work. The composition and the fact that it has such a wow impact makes this a winner !  Wonderful !', '2004-11-16 07:20:13.000000', NULL, 1),
(1013316, 120512, 92, '<td valign="top">oh my ! The compostion...lighting....rich tones and repetition make this a winner ! Wonderful photo !</td>', 'oh my ! The compostion...lighting....rich tones and repetition make this a winner ! Wonderful photo !', '2004-11-16 07:22:03.000000', NULL, 1),
(1013317, 121042, 92, '<td valign="top">So far this is my pick of the bunch ! This fits the challenge with it''s wonderful lighting, colors/tones, leading lines and that dreamy yet not blurry effect. 10</td>', 'So far this is my pick of the bunch ! This fits the challenge with it''s wonderful lighting, colors/tones, leading lines and that dreamy yet not blurry effect. 10', '2004-11-16 07:22:59.000000', NULL, 1),
(1013357, 120919, 19010, '<td valign="top">Flawless  Impressionism, Great colors and feel. Hey it''s even fun and ineresting to look at. 10</td>', 'Flawless  Impressionism, Great colors and feel. Hey it''s even fun and ineresting to look at. 10', '2004-11-16 08:37:37.000000', NULL, 1),
(1013358, 120712, 14603, '<td valign="top">Lovely variation in colour...I find the branch on the left of the picture a bit distracting though..otherwise fits the theme well.</td>', 'Lovely variation in colour...I find the branch on the left of the picture a bit distracting though..otherwise fits the theme well.', '2004-11-16 08:37:42.000000', NULL, 1),
