(1013370, 119385, 14603, '<td valign="top">This fits my idea of the challenge..my only minor niggle is that the image is "cut off" at the bottom..however, if this is a true reflection and not PS..then I know from experience the difficulties you would face in that respect.</td>', 'This fits my idea of the challenge..my only minor niggle is that the image is "cut off" at the bottom..however, if this is a true reflection and not PS..then I know from experience the difficulties you would face in that respect.', '2004-11-16 08:48:15.000000', NULL, 1),
(1013392, 120548, 28650, '<td valign="top">The soft colors and the subject matter are nearly my ideal photographic rendering of impressionism.</td>', 'The soft colors and the subject matter are nearly my ideal photographic rendering of impressionism.', '2004-11-16 09:22:42.000000', NULL, 1),
(1013438, 120752, 24925, '<td valign="top">Great work!  What an imaginative depiction of Impressionism!  I really hope this wins...<br/> <br/>I only wish that the paintbrush and hand were lit/positioned slightly differently, but that won''t stop me from handing out the first (and likely only) 9 for this challenge...</td>', 'Great work!  What an imaginative depiction of Impressionism!  I really hope this wins... I only wish that the paintbrush and hand were lit/positioned slightly differently, but that won''t stop me from handing out the first (and likely only) 9 for this challenge...', '2004-11-16 10:21:10.000000', NULL, 1),
(1013464, 120552, 9284, '<td valign="top">Fascinating!</td>', 'Fascinating!', '2004-11-16 10:37:45.000000', NULL, 1),
