(1014734, 119385, 2752, '<td valign="top">very Cezanne like.(6)</td>', 'very Cezanne like.(6)', '2004-11-17 00:09:01.000000', NULL, 1),
(1014779, 121187, 11800, '<td valign="top">I like this, but if you are the one that did the bridge, I liked that one more. The leaves in the water create a nice mellow contrast to the sharpness of the rest of the picture.</td>', 'I like this, but if you are the one that did the bridge, I liked that one more. The leaves in the water create a nice mellow contrast to the sharpness of the rest of the picture.', '2004-11-17 00:16:17.000000', NULL, 1),
(1014805, 121280, 11800, '<td valign="top">I love this. It doesn''t matter how you created it, you managed to flatten it out, the colors are moody and it tells it''s own story. Nice.</td>', 'I love this. It doesn''t matter how you created it, you managed to flatten it out, the colors are moody and it tells it''s own story. Nice.', '2004-11-17 00:21:12.000000', NULL, 1),
(1014830, 121066, 11800, '<td valign="top">I would associate this more with some of Georgia O''kefee(?) than impressionism. Don''t know if that style had a movement name, but it looks like something from her work in the 20''s. I actually have one that this looks like. The bubbles were much larger though and with softer colors. I like this a lot though and will put it in my favorites.</td>', 'I would associate this more with some of Georgia O''kefee(?) than impressionism. Don''t know if that style had a movement name, but it looks like something from her work in the 20''s. I actually have one that this looks like. The bubbles were much larger though and with softer colors. I like this a lot though and will put it in my favorites.', '2004-11-17 00:26:23.000000', NULL, 1),
(1015007, 121066, 28764, '<td valign="top">I like the colors</td>', 'I like the colors', '2004-11-17 01:07:59.000000', NULL, 1),
