(1017958, 121055, 21621, '<td valign="top">Very nice, one of my top three, great work.</td>', 'Very nice, one of my top three, great work.', '2004-11-17 19:11:25.000000', NULL, 1),
(1017972, 120919, 21621, '<td valign="top">This is a great image, I hope the subject matter doesn''t hurt your score, nice work.</td>', 'This is a great image, I hope the subject matter doesn''t hurt your score, nice work.', '2004-11-17 19:14:33.000000', NULL, 1),
(1017978, 121341, 15403, '<td valign="top">This is beautiful</td>', 'This is beautiful', '2004-11-17 19:15:48.000000', NULL, 1),
(1018006, 121076, 21621, '<td valign="top">Super, I really like this approach, good luck.</td>', 'Super, I really like this approach, good luck.', '2004-11-17 19:18:37.000000', NULL, 1),
(1018012, 120752, 9780, '<td valign="top">love it and favorited 10.</td>', 'love it and favorited 10.', '2004-11-17 19:18:56.000000', NULL, 1),
(1018061, 120176, 21621, '<td valign="top">Very nice, I really like the sky, but I''m not sure if the crisp silhouette is too much of a contrast in style.  Good luck.</td>', 'Very nice, I really like the sky, but I''m not sure if the crisp silhouette is too much of a contrast in style.  Good luck.', '2004-11-17 19:23:27.000000', NULL, 1),
(1018086, 120858, 29440, '<td valign="top">Very well exposed considering part of the photo appears to be in the fog.  Also thedepth of field covers the entire photo.  It really embraces the theme</td>', 'Very well exposed considering part of the photo appears to be in the fog.  Also thedepth of field covers the entire photo.  It really embraces the theme', '2004-11-17 19:25:33.000000', NULL, 1),
(1018166, 120552, 29440, '<td valign="top">I think the branch going out to the left leads your eye out of the photo.  Cropping it to the left of the single berry would have been more effective.  The placing of the berry group over the reflection is taking advantage of a light source and a good effect.</td>', 'I think the branch going out to the left leads your eye out of the photo.  Cropping it to the left of the single berry would have been more effective.  The placing of the berry group over the reflection is taking advantage of a light source and a good effect.', '2004-11-17 19:31:30.000000', NULL, 1),
(1018172, 120512, 24846, '<td valign="top">Like the gold color. The crop yields very nice depth.</td>', 'Like the gold color. The crop yields very nice depth.', '2004-11-17 19:33:33.000000', NULL, 1),
(1018173, 121422, 25742, '<td valign="top">I like the trees and fog, but not the close FG</td>', 'I like the trees and fog, but not the close FG', '2004-11-17 19:33:53.000000', NULL, 1),
(1018176, 120919, 25742, '<td valign="top">through hammered glass?<br/>Very modern impressionims :)</td>', 'through hammered glass?Very modern impressionims :)', '2004-11-17 19:34:25.000000', NULL, 1),
(1018180, 120752, 29440, '<td valign="top">Good composition.  This photo combines the artist''s impression of the foilage with the real foilage. The hand,brush and aeasel placement leads your eye into the photo.</td>', 'Good composition.  This photo combines the artist''s impression of the foilage with the real foilage. The hand,brush and aeasel placement leads your eye into the photo.', '2004-11-17 19:35:44.000000', NULL, 1),
(1018184, 121246, 25742, '<td valign="top">the hard rock in the FG destroy the soft feeling of this photo (they, of course, also oppose it, but too much IMHO).</td>', 'the hard rock in the FG destroy the soft feeling of this photo (they, of course, also oppose it, but too much IMHO).', '2004-11-17 19:37:30.000000', NULL, 1),
(1018186, 120512, 25742, '<td valign="top">tough subject to impressionismize but quite well done.</td>', 'tough subject to impressionismize but quite well done.', '2004-11-17 19:39:17.000000', NULL, 1),
(1018187, 121055, 29440, '<td valign="top">The warm colors blend together.  I think of early landscape artists when I first viewed this photo.  The almost darkened trees and bushes give the right amount of contrast.</td>', 'The warm colors blend together.  I think of early landscape artists when I first viewed this photo.  The almost darkened trees and bushes give the right amount of contrast.', '2004-11-17 19:40:05.000000', NULL, 1),
(1018188, 121042, 25742, '<td valign="top">very Monet like</td>', 'very Monet like', '2004-11-17 19:40:05.000000', NULL, 1),
(1018204, 120919, 29440, '<td valign="top">I can see the delivery man working in a summer rain storm. His head is bent forward to avoid the rain and it must be warm weather because he is wearing shorts.  The computer programs available has turned the photo into an impressionist photo.</td>', 'I can see the delivery man working in a summer rain storm. His head is bent forward to avoid the rain and it must be warm weather because he is wearing shorts.  The computer programs available has turned the photo into an impressionist photo.', '2004-11-17 19:45:43.000000', NULL, 1),
(1018266, 120712, 4411, '<td valign="top">The colour is great, and while I could probably live with the soft look I don''t like the big black blotch across the photo at all. What is it?</td>', 'The colour is great, and while I could probably live with the soft look I don''t like the big black blotch across the photo at all. What is it?', '2004-11-17 20:12:08.000000', NULL, 1),
(1018279, 119385, 4411, '<td valign="top">Very nice colours, however the bottom of the house being cut off doesn''t appeal to me. I feel like I''m only seeing a part of a bigger photo.</td>', 'Very nice colours, however the bottom of the house being cut off doesn''t appeal to me. I feel like I''m only seeing a part of a bigger photo.', '2004-11-17 20:20:14.000000', NULL, 1),
(1018327, 120858, 28982, '<td valign="top">the contrasting colors are beautiful and the fade suits this shot well.  great shot.</td>', 'the contrasting colors are beautiful and the fade suits this shot well.  great shot.', '2004-11-17 20:47:12.000000', NULL, 1),
(1018341, 121025, 14763, '<td valign="top">WoW Great Capture  10</td>', 'WoW Great Capture  10', '2004-11-17 20:51:51.000000', NULL, 1),
