(1026155, 119970, 16301, '<td valign="top">Colors and composition are all great, nice effect too...</td>', 'Colors and composition are all great, nice effect too...', '2004-11-21 21:42:46.000000', NULL, 1),
(1026157, 120752, 16301, '<td valign="top">Very creative way to meet the challenge, nice colors...</td>', 'Very creative way to meet the challenge, nice colors...', '2004-11-21 21:43:38.000000', NULL, 1),
(1026158, 121042, 17203, '<td valign="top">Great effect captured in the water, though the subject''s a little <i>too</i> ambiguous for my taste. Something sharp, like a leaf or a duck would polish it off for me. Still, this should easily place in the top ten. 8</td>', 'Great effect captured in the water, though the subject''s a little too ambiguous for my taste. Something sharp, like a leaf or a duck would polish it off for me. Still, this should easily place in the top ten. 8', '2004-11-21 21:43:45.000000', NULL, 1),
