(1026420, 121055, 22734, '<td valign="top">Brad you never fail to amaze me and your friends. You are on the cutting edge and indeed a marvel. Congrats on your yellow in this very demmanding challenge. Another feather in your cap and I am very happy for you.</td>', 'Brad you never fail to amaze me and your friends. You are on the cutting edge and indeed a marvel. Congrats on your yellow in this very demmanding challenge. Another feather in your cap and I am very happy for you.', '2004-11-22 00:06:05.000000', NULL, 0),
(1026422, 117658, 16301, '<td valign="top">Congrats on 5th place Dan!</td>', 'Congrats on 5th place Dan!', '2004-11-22 00:06:47.000000', NULL, 0),
(1026426, 121324, 22734, '<td valign="top">Happy to tag behind this beautiful image. Congrats on your 4th finish in this great competition.</td>', 'Happy to tag behind this beautiful image. Congrats on your 4th finish in this great competition.', '2004-11-22 00:07:46.000000', NULL, 0),
